values
  ('physics-board-jessore-2023-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p68', 'বাল্বটির রোধ কত?', 'mcq', '{"ক":"0. 0012σ","খ":"0.273σ","গ":"3.667σ","ঘ":"806.67σ"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, 'একটি বৈদ্যুতিক বাল্বের গায়ে 60W-220V লেখা আছে।', 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-022', 'class9-physics-bn-guide', 'satt-physics-board.pdf p69', 'বাল্বটিকে দৈনিক ৬ ঘণ্টা ব্যবহার করলে এপ্রিল মাসে কত ইউনিট বিদ্যুৎ খরচ হবে?', 'mcq', '{"ক":"1.116","খ":"1.8","গ":"10.8","ঘ":"11.16"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, 'একটি বৈদ্যুতিক বাল্বের গায়ে 60W-220V লেখা আছে।', 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-023', 'class9-physics-bn-guide', 'satt-physics-board.pdf p69', 'বর্তনীর তূ ল্যরোধ কত?', 'mcq', '{"ক":"10","খ":"12","গ":"24","ঘ":"30"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2023-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p69', 'চিত্রানুযায়ী — i. I = I2 + I1 ii. I1 > I2 iii. V1 = V2 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2023-mcq', false, 'board-mcq', null, null, 'jessore', 2023, true),
  ('physics-board-jessore-2024-mcq-001', 'class9-physics-bn-guide', 'satt-physics-board.pdf p19', 'সুপ্ত তাপের ক্ষেত্রে- i. বস্তুর অবস্থার পরিবর্তন হয় ii. বস্তুর তাপ স্থির থাকে iii. বস্তুর তাপমাত্রা স্থির থাকে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-002', 'class9-physics-bn-guide', 'satt-physics-board.pdf p19', 'শব্দের তীব্রতার একক কী?', 'mcq', '{"ক":"S","খ":"Hz","গ":"W","ঘ":"W m −2"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-003', 'class9-physics-bn-guide', 'satt-physics-board.pdf p19', 'একট ক্রেন দ্বারা 10 kg ভরের কোনো বস্তুকে 2 মিনিটে 10 m উচ্চতায় উঠানো হলে- [ g = 9.8 ms-2] i. কৃ তকাজ ঋণাত্মক ii. বিভব শক্তি 980 J iii. কার্যকর ক্ষমতা 490 W নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-004', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'জেনারেটরের কাজ কী?', 'mcq', '{"ক":"রাসায়নিক শক্তি থেকে তড়িৎশক্তিতে রূপান্তর","খ":"তড়িৎ বিভব শক্তির বিবর্ধন","গ":"যান্ত্রিক শক্তি থেকে তড়িৎশক্তিতে রূপান্তর","ঘ":"তড়িৎশক্তির বিবর্ধন"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-005', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', '10 kg ভরের কোনো বস্তুর আয়তন 0.01 m3. বস্তুটি পানিতে কী অবস্থায় ভাসবে?', 'mcq', '{"ক":"পাত্রের তলদেশে স্থির হবে","খ":"সম্পূর্ণ নিমজ্জিত অবস্থায় ভাসবে","গ":"অর্ধেক নিমজ্জিত অবস্থায় ভাসবে","ঘ":"সম্পূর্ণ ভেসে থাকবে"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-006', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'কোন যন্ত্র নিউক্লিয় চৌম্বক অনুনাদ এর ভৌত ও রাসায়নিক নীতির উপর ভিত্তি করে কাজ করে?', 'mcq', '{"ক":"সিটি স্ক্যান","খ":"ই.সি.জি","গ":"এন্ডোসকপি","ঘ":"এম.আর.আই"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-007', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'সূক্ষ্ম রক্তনালিকার ব্লকেজ পরীক্ষা করার প্রযুক্তি কোনটি?', 'mcq', '{"ক":"এনজিওপ্লাস্টি","খ":"এনজিওগ্রাম","গ":"ই.সি.জি","ঘ":"ই.টি.টি"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'নিচের কোনটি লব্ধ একক?', 'mcq', '{"ক":"অ্যম্পিয়ার","খ":"কেলভিন","গ":"নিউটন","ঘ":"ক্যান্ডেলা"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'লেখচিত্রটি কী প্রদর্শন করে?', 'mcq', '{"ক":"সমমন্দনে","খ":"সমত্বরণে","গ":"সমবেগে","ঘ":"অসমত্বরণে"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-010', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', '72 kmh-1 বেগে খাড়া উপরের দিকে নিক্ষিপ্ত বস্তু কত উচ্চতায় উঠবে? [ g = 9.8ms-2]', 'mcq', '{"ক":"264.49 km","খ":"264.49 m","গ":"20.4 km","ঘ":"20.4 m"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-011', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'উত্তল দর্পণের প্রতিবিম্বের ক্ষেত্রে কোনটি সঠিক?', 'mcq', '{"ক":"অবাস্তব ও উল্টা","খ":"বাস্তব ও সোজা","গ":"বাস্তব ও উল্টা","ঘ":"অবাস্তব ও সোজা"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p20', 'ক্ষীণ দৃষ্টির কারণে - i. চক্ষু লেন্সের অভিসারী ক্ষমতা বেড়ে যায়। ii. অক্ষিগোলকের ব্যাসার্ধ কমে যায় iii. চক্ষু লেন্সের ফোকাস দূরত্ব কমে যায় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-013', 'class9-physics-bn-guide', 'satt-physics-board.pdf p21', 'লেন্সের বক্রতার কেন্দ্রের সংযোগকারী সরলরেখাকে কী বলে?', 'mcq', '{"ক":"ফোকাস","খ":"বক্রতার কেন্দ্র","গ":"আলোক কেন্দ্র","ঘ":"প্রধান অক্ষ"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-014', 'class9-physics-bn-guide', 'satt-physics-board.pdf p21', 'অসীম দূরত্ব থেকে তড়িৎক্ষেত্রের কোনো বিন্দুতে একটি একক ধনাত্মক আধানকে আনতে যে কাজ করতে হয় তাকে কী বলে?', 'mcq', '{"ক":"তড়িৎধারক","খ":"তড়িৎ বল","গ":"তড়িৎ বিভব","ঘ":"তড়িৎ তীব্রতা"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-015', 'class9-physics-bn-guide', 'satt-physics-board.pdf p21', 'কোনো তড়িৎ বস্তুকে স্পর্শ করলে - i. ইলেকট্রন হারাতে পারে ii. শুধু ঋণাত্মক আধান লাভ করতে পারে iii. তড়িতাহত হতে পারে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-016', 'class9-physics-bn-guide', 'satt-physics-board.pdf p21', 'চিত্রে প্রদর্শিত বর্তনীর ক্ষমতা কত?', 'mcq', '{"ক":"4.5 W","খ":"2.25 W","গ":"1.5 W","ঘ":"0.75 W"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-017', 'class9-physics-bn-guide', 'satt-physics-board.pdf p21', 'সার্কিট ব্রেকারের মাধ্যমে- i. বিদ্যুৎ প্রবাহ হ্রাস-বৃদ্ধি করা যায় ii. নির্দিষ্ট মাত্রার অতিরিক্ত বিদ্যুৎ প্রবাহ হলে বর্তনী বিচ্ছিন্ন করা হয় iii. বৈদ্যুতিক দুর্ঘটনা থেকে যন্ত্রপাতি রক্ষা করে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-018', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'ক্যাবল টিভি কোনটির সাহায্যে সংকেত পাঠায়?', 'mcq', '{"ক":"অ্যান্টেনা","খ":"রিসিভার","গ":"টাওয়ার","ঘ":"কো এক্সিয়াল ক্যাবল"}'::jsonb, 'ঘ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-019', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'একটি সুইচের সাথে অনেকগুলো কম্পিউটার যুক্ত করার ক্ষেত্রে নিম্নের কোনটি সঠিক?', 'mcq', '{"ক":"LAN","খ":"NAL","গ":"BTS","ঘ":"Internet"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, null, 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-020', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'বস্তুটির প্রকৃ ত ওজন কত?', 'mcq', '{"ক":"5 kg","খ":"5 N","গ":"49 N","ঘ":"500 N"}'::jsonb, 'গ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, '5 kg ভরের একটি বস্তুকে পানিতে নিমজ্জিত করা হলো। বস্তুটির আয়তন 500 cm3. [ g = 9.8 ms-2 ] পানির ঘনত্ব 1000 kg/m3.', 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'পানিতে নিমজ্জিত অবস্থায় বস্তুটির উপর ক্রিয়াশীল উর্ধ্বমুখী বল কত?', 'mcq', '{"ক":"4.9 N","খ":"5N","গ":"500 N","ঘ":"2500 N"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, '5 kg ভরের একটি বস্তুকে পানিতে নিমজ্জিত করা হলো। বস্তুটির আয়তন 500 cm3. [ g = 9.8 ms-2 ] পানির ঘনত্ব 1000 kg/m3.', 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-022', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'বস্তুদ্বয়ের মিলিত বেগ কত?', 'mcq', '{"ক":"2 ms −1","খ":"6 ms −1","গ":"8. 67 ms −1","ঘ":"26 ms −1"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, 'P = 6kg Q = 3kg ভরের দুটি বস্তু একই সরলরেখায় পরস্পর অভিমুখে চলে সংঘর্ষ হলো। সংঘর্ষের পূর্বে তাদের বেগ যথাক্রমে 8ms-1 ও 10ms-1', 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-023', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'মিলিত বস্তুদ্বয়ের অভিমুখ কোন দিকে হবে?', 'mcq', '{"ক":"P বস্তুর দিকে","খ":"Q বস্তুর দিকে","গ":"পরস্পর বিপরীত দিকে","ঘ":"স্থির হয়ে যাবে"}'::jsonb, 'ক', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, 'P = 6kg Q = 3kg ভরের দুটি বস্তু একই সরলরেখায় পরস্পর অভিমুখে চলে সংঘর্ষ হলো। সংঘর্ষের পূর্বে তাদের বেগ যথাক্রমে 8ms-1 ও 10ms-1', 'jessore', 2024, true),
  ('physics-board-jessore-2024-mcq-024', 'class9-physics-bn-guide', 'satt-physics-board.pdf p22', 'সেকেন্ডারি কয়েলের ভোল্টেজ কত?', 'mcq', '{"ক":"0.02V","খ":"50V","গ":"312.50V","ঘ":"968V"}'::jsonb, 'খ', 1, false, 'physics-board-jessore-2024-mcq', false, 'board-mcq', null, 'একটি ট্রান্সফর্মারে প্রাইমারি কয়েলের পাক সংখ্যা 550. সেকেন্ডারি কয়েলের পাক সংখ্যা 125. প্রাইমারি কয়েল দিয়ে 220V AC দেওয়া হলো।', 'jessore', 2024, true),
