  ('physics-board-mymensingh-2021-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p97', 'এক টু করো কাচে শতকরা কত ভাগ আলোর প্রতিফলন হয়?', 'mcq', '{"ক":"4 থেকে 5 ভাগ","খ":"40 থেকে 50 ভাগ","গ":"80 থেকে 90 ভাগ","ঘ":"95 থেকে 96 ভাগ"}'::jsonb, 'ক', 1, false, 'physics-board-mymensingh-2021-mcq', false, 'board-mcq', null, null, 'mymensingh', 2021, true),
  ('physics-board-mymensingh-2021-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p97', 'একটি লাল গোলাপকে কোনো দর্পণের সামনে কত ডিগ্রী কোণে স্থাপন করলে সবচেয়ে বেশি উজ্জ্বল দেখাবে?', 'mcq', '{"ক":"30°","খ":"45°","গ":"60°","ঘ":"75°"}'::jsonb, 'ঘ', 1, false, 'physics-board-mymensingh-2021-mcq', false, 'board-mcq', null, null, 'mymensingh', 2021, true),
  ('physics-board-mymensingh-2021-mcq-010', 'class9-physics-bn-guide', 'satt-physics-board.pdf p97', 'দুটি আয়নাকে কত ডিগ্রী কোণে যুক্ত করে একটি আয়না হিসেবে গঠন করলে তাতে প্রতিবিম্বের পার্শ্ব পরিবর্তন বুঝা যাবে না?', 'mcq', '{"ক":"30°","খ":"45°","গ":"1 60°","ঘ":"90°"}'::jsonb, 'ঘ', 1, false, 'physics-board-mymensingh-2021-mcq', false, 'board-mcq', null, null, 'mymensingh', 2021, true),
