  ('physics-board-mymensingh-2021-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p97', 'স্লাইড ক্যালিপার্সের সাহায্যে একটি দণ্ডের দৈর্ঘ্য, নির্ণয়ের ক্ষেত্রে, প্রধান স্কেল পাঠ M, ভার্নিয়ার ধ্রুবক VC এবং ভার্নিয়ার সমপাতন V হলে দণ্ডের দৈর্ঘ্য (L) নির্ণয়ের সূত্র নিচের কোনটি?', 'mcq', '{"ক":"L = M − V × V C","খ":"L = M + V × V C","গ":"L = M − V ÷ V C","ঘ":"L = M + V ÷ V C"}'::jsonb, 'খ', 1, false, 'physics-board-mymensingh-2021-mcq', false, 'board-mcq', null, null, 'mymensingh', 2021, true),
