  ('physics-board-mymensingh-2022-mcq-008', 'class9-physics-bn-guide', 'satt-physics-board.pdf p41', 'তরঙ্গের কোনো কণার পর্যায়কাল বেশি হলে কী ঘটবে?', 'mcq', '{"ক":"কম্পাঙ্ক কমে যাবে","খ":"কম্পাঙ্ক বেড়ে যাবে","গ":"কম্পাঙ্ক থেমে যাবে","ঘ":"কম্পাঙ্ক সমান থাকবে"}'::jsonb, 'ক', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', null, null, 'mymensingh', 2022, true),
  ('physics-board-mymensingh-2022-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p41', 'দুটি সুর শলাকার কম্পাঙ্ক 200 Hz ও 800 Hz, শলাকা দুটি হতে প্রাপ্ত তরঙ্গ দৈর্ঘ্যের অনুপাত কত?', 'mcq', '{"ক":"1:4","খ":"4:1","গ":"1:2","ঘ":"2:1"}'::jsonb, 'খ', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', null, null, 'mymensingh', 2022, true),
  ('physics-board-mymensingh-2022-mcq-011', 'class9-physics-bn-guide', 'satt-physics-board.pdf p41', 'কোনো নির্দিষ্ট ভরের কোনো বস্তুর বেগ দ্বিগুণ করলে গতিশক্তি কত গুণ হবে?', 'mcq', '{"ক":"চারগুণ","খ":"দ্বিগুণ","গ":"অর্ধেক","ঘ":"সমান"}'::jsonb, 'ক', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', null, null, 'mymensingh', 2022, true),
  ('physics-board-mymensingh-2022-mcq-012', 'class9-physics-bn-guide', 'satt-physics-board.pdf p41', '1 পিকোমিটার = কত সেন্টিমিটার?', 'mcq', '{"ক":"10 −8","খ":"10 −16","গ":"10 −12","ঘ":"10 −10"}'::jsonb, 'ঘ', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', null, null, 'mymensingh', 2022, true),
  ('physics-board-mymensingh-2022-mcq-013', 'class9-physics-bn-guide', 'satt-physics-board.pdf p41', 'একটি দণ্ডকে স্লাইড ক্যালিপার্সের সাহায্যে পরিমাপ করতে গিয়ে তার প্রধান স্কেল পাঠ 5 cm, ভার্নিয়ার সমপাতন 7 এবং ভার্নিয়ার ধ্রুবক 0.1 mm। দণ্ডটির দৈর্ঘ্য নির্ণয় কর।', 'mcq', '{"ক":"5.7 cm","খ":"5.7 mm","গ":"5.07mm","ঘ":"5.07 cm"}'::jsonb, 'ঘ', 1, false, 'physics-board-mymensingh-2022-mcq', false, 'board-mcq', null, null, 'mymensingh', 2022, true),
