  ('physics-board-rajshahi-2019-mcq-009', 'class9-physics-bn-guide', 'satt-physics-board.pdf p200', 'একটি ট্রান্সফর্মারের মুখ্য ও গৌণ কু ণ্ডলীর পাক-সংখ্যা যথাক্রমে 30 এবং 150 গৌণ কু ণ্ডলীর তড়িৎ প্রবাহ 2A হলে মুখ্য কু ণ্ডলীর তড়িৎ প্রবাহ কত?', 'mcq', '{"ক":"0.1 A","খ":"0.4 A","গ":"2.5 A","ঘ":"10 A"}'::jsonb, 'ঘ', 1, false, 'physics-board-rajshahi-2019-mcq', false, 'board-mcq', null, null, 'rajshahi', 2019, true),
