  ('physics-board-rajshahi-2020-mcq-017', 'class9-physics-bn-guide', 'satt-physics-board.pdf p172', 'অবতল দর্পণের ফোকাস দূরত্বের দ্বিগুণ দূরত্বে একটি বস্তু রাখলে এর প্রতিবিম্ব হবে- i. বক্রতার কেন্দ্রে ii. উল্টো iii. বস্তুর আকারের সমান নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'physics-board-rajshahi-2020-mcq', false, 'board-mcq', null, null, 'rajshahi', 2020, true),
  ('physics-board-rajshahi-2020-mcq-018', 'class9-physics-bn-guide', 'satt-physics-board.pdf p172', 'পরিবর্তনশীল চৌম্বকক্ষেত্রের দ্বারা কোনো বর্তনীতে তড়িৎ প্রবাহ সৃষ্টির ঘটনাকে কী বলে?', 'mcq', '{"ক":"তড়িৎ আবেশ","খ":"তাড়িৎচৌম্বক আবেশ","গ":"চৌম্বক আবেশ","ঘ":"চৌম্বক প্রাবল্য"}'::jsonb, 'খ', 1, false, 'physics-board-rajshahi-2020-mcq', false, 'board-mcq', null, null, 'rajshahi', 2020, true),
  ('physics-board-rajshahi-2020-mcq-020', 'class9-physics-bn-guide', 'satt-physics-board.pdf p173', 'পানির গৃহীত তাপ কত?', 'mcq', '{"ক":"16380J","খ":"18900 J","গ":"35280 J","ঘ":"16380000 J"}'::jsonb, 'ক', 1, false, 'physics-board-rajshahi-2020-mcq', false, 'board-mcq', null, '30°C তাপমাত্রার 150g পানিতে 75°C তাপমাত্রার লোহার দণ্ড নিমজ্জিত করা হলো এবং চূ ড়ান্ত তাপমাত্রা 56°C হলো। পানির আপেক্ষিক তাপ 4200J kg-1 K-1, লোহার আপেক্ষিক তাপ ও ঘনত্ব যথাক্রমে 450J kg-1 K-1 এবং 7800kg m-3.', 'rajshahi', 2020, true),
  ('physics-board-rajshahi-2020-mcq-021', 'class9-physics-bn-guide', 'satt-physics-board.pdf p173', 'উক্ত ঘটনায়— i. লোহার দণ্ডের বর্জিত তাপ = পানির গৃহীত তাপ ii. লোহার ভর = 9 x পানির ভর iii. পানির তাপধারণ ক্ষমতা < লোহার দণ্ডের তাপধারণ ক্ষমতা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"ii","খ":"iii","গ":"i ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'physics-board-rajshahi-2020-mcq', false, 'board-mcq', null, '30°C তাপমাত্রার 150g পানিতে 75°C তাপমাত্রার লোহার দণ্ড নিমজ্জিত করা হলো এবং চূ ড়ান্ত তাপমাত্রা 56°C হলো। পানির আপেক্ষিক তাপ 4200J kg-1 K-1, লোহার আপেক্ষিক তাপ ও ঘনত্ব যথাক্রমে 450J kg-1 K-1 এবং 7800kg m-3.', 'rajshahi', 2020, true),
